//! Per-glyph metrics of the formula font (ADR-T33-1), in em, y up.
//!
//! [`TABLE`] has one row per character of the embedded Latin Modern Math
//! subset; [`get`] looks one up. The rows are generated by
//! `scripts/math_metrics.py` from the font, and a shell test checks them
//! against it, so `core` lays formulas out without a font.

/// Metrics of one glyph, in em of the font size, y up.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GlyphMetrics {
    /// Horizontal advance.
    pub advance: f32,
    /// Left of the ink, right of the pen.
    pub x_min: f32,
    /// Right of the ink, right of the pen.
    pub x_max: f32,
    /// Bottom of the ink above the baseline (negative: below).
    pub y_min: f32,
    /// Top of the ink above the baseline.
    pub y_max: f32,
    /// Italic correction: room a superscript leaves after the glyph.
    pub italic: f32,
}

/// Shorthand for a table row.
const fn m(
    advance: f32,
    x_min: f32,
    x_max: f32,
    y_min: f32,
    y_max: f32,
    italic: f32,
) -> GlyphMetrics {
    GlyphMetrics {
        advance,
        x_min,
        x_max,
        y_min,
        y_max,
        italic,
    }
}

/// The metrics of `ch`, if the math font has it.
#[must_use]
pub fn get(ch: char) -> Option<GlyphMetrics> {
    TABLE
        .binary_search_by(|row| row.0.cmp(&ch))
        .ok()
        .and_then(|i| TABLE.get(i))
        .map(|row| row.1)
}

